#!/usr/bin/env node
// The discovery evaluation loop: run discovery on every ground-truth example and compare with the
// last run (or a named baseline). Each example is generated by a known system dynamics model, so
// discovery is graded two ways:
//   parts    - parts of the true model recovered in the right form (relationships of the right kind,
//              flows to or from outside), out of all of them
//   skill@H  - the share of the true model's movement over H steps that the found model predicts,
//              both started from the same states and fed the same outside inflows (1 = behaves the
//              same as the truth; 0 = no better than assuming nothing changes; below 0 = worse)
//
//   node tests/bench/evaluate.mjs                       all ground-truth examples, compared with the last run
//   node tests/bench/evaluate.mjs --label "try X"       name this run (shown in comparisons)
//   node tests/bench/evaluate.mjs --baseline best       compare with the run saved as "best" (--save best to save)
//   node tests/bench/evaluate.mjs --examples sd-saas,sd-orders --lengths default
//   node tests/bench/evaluate.mjs --strict              exit 1 if any skill@20 drops by more than 0.02
//   node tests/bench/evaluate.mjs --jobs 4              at most 4 examples at once (default: CPU cores - 1)
//   node tests/bench/evaluate.mjs --goal                check the goal (docs/DISCOVERY-GOAL.md): every
//                                                       example at every length at least GOAL_SKILL20 at
//                                                       skill@20 and GOAL_SKILL100 at skill@100; exit 0 only
//                                                       when it is met (exit 2 otherwise)
//
// Examples run in parallel, one process per example and length.
// Runs are saved under ~/.cache/sdlab/bench/runs (or $SDLAB_BENCH_CACHE/runs), never in the repository.
import fs from "fs";
import os from "os";
import path from "path";
import { spawn, spawnSync } from "child_process";
import { createRequire } from "module";
import { truthOf, grade, sameBehaviour } from "./grade.mjs";

const require = createRequire(import.meta.url);
const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "../..");
const arg = (name, dflt) => { const i = process.argv.indexOf(`--${name}`); return i < 0 ? dflt : process.argv[i + 1]; };
const flag = (name) => process.argv.includes(`--${name}`);
const CACHE = process.env.SDLAB_BENCH_CACHE || path.join(process.env.HOME, ".cache", "sdlab", "bench");
const RUNS = path.join(CACHE, "runs");
fs.mkdirSync(RUNS, { recursive: true });

const examples = (arg("examples") || fs.readdirSync(path.join(ROOT, "sdlab/examples")).filter((d) => d.startsWith("sd-") && fs.existsSync(path.join(ROOT, "sdlab/examples", d, "truth.model.json"))).sort().join(",")).split(",");
const lengths = (arg("lengths", "default,long")).split(",");
const HORIZONS = [5, 20, 100];
const engineName = arg("engine", "identify");
const engine = engineName === "identify" ? require(path.join(ROOT, "sdlab/static/identify.js")).identify
  : ((d) => (stocks, run, opts) => (stocks.length > 12 ? d.discoverAll : d.discover)(stocks, run, { window: 5, ...opts }))(require(path.join(ROOT, "sdlab/static/discover.js")));

function dataset(example, length) {
  const p = spawnSync("uv", ["run", "--directory", ROOT, "python", "tests/bench/datasets.py", example, ...(length === "long" ? ["--long"] : length === "default" ? [] : ["--steps", length])], { encoding: "utf8", maxBuffer: 1 << 26 });
  if (p.status !== 0) throw new Error(`${example}: ${p.stderr.trim().split("\n").pop()}`);
  return JSON.parse(fs.readFileSync(p.stdout.trim().split("\n").pop()));
}

function evaluateOne(example, length) {
  const model = JSON.parse(fs.readFileSync(path.join(ROOT, "sdlab/examples", `${example}.json`)));
  const truthModel = JSON.parse(fs.readFileSync(path.join(ROOT, "sdlab/examples", example, "truth.model.json")));
  const truth = truthOf(example);
  const data = dataset(example, length);
  const eras = (data.eras || []).map((e) => ({ start: e.start }));
  const t0 = Date.now();
  let r, error = null;
  try { r = engine(model.stocks, { t: data.t, levels: data.levels, rates: {} }, { eras: eras.length > 1 ? eras : undefined }); }
  catch (e) { error = String(e && e.stack || e).split("\n").slice(0, 3).join(" "); r = { flows: [] }; }
  const ms = Date.now() - t0, g = grade(r, truth);
  const skill = Object.fromEntries(HORIZONS.map((H) => [H, sameBehaviour(r, truthModel, data, { horizon: H }).skill]));
  return { example, length, steps: data.t.length, parts: g.right, of: g.parts, skill, ms, flows: r.flows.length, error };
}

// a worker: one example at one length, its result as JSON on stdout
if (flag("worker")) {
  const i = process.argv.indexOf("--worker");
  process.stdout.write(JSON.stringify(evaluateOne(process.argv[i + 1], process.argv[i + 2])));
  process.exit(0);
}

const jobs = [];
examples.forEach((example) => lengths.forEach((length) => jobs.push({ example, length })));
const width = Math.max(1, +arg("jobs", Math.max(1, os.cpus().length - 1)));
const results = await new Promise((resolve) => {
  const out = new Array(jobs.length);
  let next = 0, running = 0, done = 0;
  const launch = () => {
    while (running < width && next < jobs.length) {
      const k = next++, { example, length } = jobs[k];
      running++;
      const child = spawn(process.execPath, [new URL(import.meta.url).pathname, "--worker", example, length, "--engine", engineName], { stdio: ["ignore", "pipe", "pipe"] });
      let stdout = "", stderr = "";
      child.stdout.on("data", (d) => { stdout += d; });
      child.stderr.on("data", (d) => { stderr += d; });
      child.on("close", () => {
        try { out[k] = JSON.parse(stdout); } catch { out[k] = { example, length, steps: 0, parts: 0, of: 0, skill: Object.fromEntries(HORIZONS.map((H) => [H, -1])), ms: 0, flows: 0, error: (stderr || "no result").trim().split("\n").slice(-3).join(" ") }; }
        const x = out[k];
        process.stderr.write(`  ${x.example} ${x.length}: ${x.parts}/${x.of} parts, skill@20 ${(+x.skill[20]).toFixed(3)}, ${x.ms} ms${x.error ? " ERROR " + x.error : ""}\n`);
        running--; done++;
        if (done === jobs.length) resolve(out); else launch();
      });
    }
  };
  launch();
});

const label = arg("label", "");
const run = { at: new Date().toISOString(), label, engine: engineName, results };
const file = path.join(RUNS, `${run.at.replace(/[:.]/g, "-")}${label ? "-" + label.replace(/[^a-z0-9]+/gi, "-").slice(0, 40) : ""}.json`);
fs.writeFileSync(file, JSON.stringify(run, null, 1));

// the run to compare with: a named baseline, or the previous run
const saved = fs.readdirSync(RUNS).filter((f) => f.endsWith(".json") && path.join(RUNS, f) !== file).sort();
const baseName = arg("baseline");
// without a named baseline: the latest earlier run that covered every example and length run now
// (a quick run of one example must not become what a full run is compared with)
const covers = (f) => { try { const r = JSON.parse(fs.readFileSync(path.join(RUNS, f))); return results.every((x) => r.results.some((b) => b.example === x.example && b.length === x.length)); } catch { return false; } };
const baseFile = baseName ? (fs.existsSync(path.join(RUNS, `baseline-${baseName}.json`)) ? path.join(RUNS, `baseline-${baseName}.json`) : null)
  : ((f) => (f ? path.join(RUNS, f) : null))(saved.filter((f) => !f.startsWith("baseline-")).reverse().find(covers));
const base = baseFile ? JSON.parse(fs.readFileSync(baseFile)) : null;
const before = (x) => base && base.results.find((b) => b.example === x.example && b.length === x.length);
const pct = (v) => (v === undefined || v === null ? "-" : `${(100 * v).toFixed(1)}%`);
const delta = (now, then, digits = 1) => (then === undefined ? "" : ((d) => (Math.abs(d) < 0.05 / 100 ? "" : ` (${d > 0 ? "+" : ""}${(100 * d).toFixed(digits)})`))(now - then));

const lines = [`Discovery evaluation: ${run.at}${label ? ` "${label}"` : ""} (${engineName})${base ? `, compared with ${base.at}${base.label ? ` "${base.label}"` : ""}` : ""}`, "",
  "| example | length | parts | skill@5 | skill@20 | skill@100 | time |", "|---|---|---|---|---|---|---|"];
results.forEach((x) => {
  const b = before(x);
  lines.push(`| ${x.example} | ${x.length} (${x.steps}) | ${x.parts}/${x.of}${b && b.parts !== x.parts ? ` (${x.parts > b.parts ? "+" : ""}${x.parts - b.parts})` : ""} | ` +
    HORIZONS.map((H) => `${pct(x.skill[H])}${b ? delta(x.skill[H], b.skill[H]) : ""}`).join(" | ") + ` | ${x.ms} ms${x.error ? " ERROR" : ""} |`);
});
const mean = (rs, H) => rs.reduce((a, x) => a + Math.max(-1, x.skill[H]), 0) / Math.max(1, rs.length);
const partsShare = (rs) => rs.reduce((a, x) => a + x.parts, 0) / Math.max(1, rs.reduce((a, x) => a + x.of, 0));
lines.push("", `Overall: parts ${pct(partsShare(results))}${base ? delta(partsShare(results), partsShare(base.results)) : ""}, mean skill@20 ${pct(mean(results, 20))}${base ? delta(mean(results, 20), mean(base.results, 20)) : ""}, mean skill@100 ${pct(mean(results, 100))}${base ? delta(mean(results, 100), mean(base.results, 100)) : ""}`);
const regressions = base ? results.filter((x) => { const b = before(x); return b && x.skill[20] < b.skill[20] - 0.02; }) : [];
if (regressions.length) lines.push(`Worse by more than 2 points at skill@20: ${regressions.map((x) => `${x.example} (${x.length})`).join(", ")}`);
console.log(lines.join("\n"));
console.log(`\nSaved ${file}`);
if (arg("save")) { fs.copyFileSync(file, path.join(RUNS, `baseline-${arg("save")}.json`)); console.log(`Saved as baseline "${arg("save")}"`); }
if (flag("strict") && regressions.length) process.exit(1);

// the goal: every ground-truth example, at every length, behaves close enough to its true model
const GOAL_SKILL20 = 0.9, GOAL_SKILL100 = 0.8;
if (flag("goal")) {
  const short = results.filter((x) => x.error || !(x.skill[20] >= GOAL_SKILL20) || !(x.skill[100] >= GOAL_SKILL100));
  const all = fs.readdirSync(path.join(ROOT, "sdlab/examples")).filter((d) => d.startsWith("sd-") && fs.existsSync(path.join(ROOT, "sdlab/examples", d, "truth.model.json")));
  const missing = all.filter((e) => !results.some((x) => x.example === e));
  console.log(`\nGoal (skill@20 >= ${pct(GOAL_SKILL20)} and skill@100 >= ${pct(GOAL_SKILL100)} for every example at every length): ` +
    (short.length || missing.length ? `NOT MET - ${results.length - short.length} of ${results.length} runs meet it` : `MET for all ${results.length} runs`));
  short.forEach((x) => console.log(`  short: ${x.example} (${x.length}): skill@20 ${pct(x.skill[20])}, skill@100 ${pct(x.skill[100])}${x.error ? ", error" : ""}`));
  if (missing.length) console.log(`  not run (run without --examples to check the goal): ${missing.join(", ")}`);
  process.exit(short.length || missing.length ? 2 : 0);
}
